/* ================== PARAMETER ================== *//*SELECT FROM OJDT H */DECLARE @FromDate DATE;DECLARE @ToDate   DATE;SET @FromDate = /* H.RefDate */ N'[%0]';SET @ToDate   = /* H.RefDate */ N'[%1]';/* ================== BEAS COST DETAIL – ITEM COST ================== */WITH BEAS_COST_DETAIL AS(    /* =======================================================       1. BEAS JOURNAL HISTORIE       ======================================================= */    SELECT        J.TransId,        J.U_belnrid              AS BELNR_ID,        J.U_belposid             AS BELPOS_ID,        O.AcctCode               AS Account,        J.Debit,        J.Credit,        NULL                     AS ItemCode,        NULL                     AS Quantity,        NULL                     AS WhsCode,        NULL                     AS ItemGroup,        NULL                     AS ItemCost,        NULL                     AS ItemAmount,        OJ.RefDate               AS PostingDate,        'BEAS_JOURNAL_HISTORIE'  AS SrcType    FROM BEAS_JOURNAL_HISTORIE J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    LEFT JOIN OACT O   ON J.Account = O.AcctCode    WHERE J.U_belnrid  IS NOT NULL      AND J.U_belposid IS NOT NULL    UNION ALL    /* =======================================================       2. JE thường (KHÔNG GI / GR)       ======================================================= */    SELECT        J.TransId,        OJ.U_belnrid,        OJ.U_belposid,        O.AcctCode,        J.Debit,        J.Credit,        NULL,        NULL,        NULL,        NULL,        NULL,        NULL,        OJ.RefDate               AS PostingDate,        'JE_NORMAL'    FROM JDT1 J    INNER JOIN OJDT OJ ON OJ.TransId = J.TransId    LEFT JOIN OACT O   ON J.Account = O.AcctCode    WHERE OJ.TransType NOT IN (59,60)      AND OJ.U_belnrid  IS NOT NULL      AND OJ.U_belposid IS NOT NULL    UNION ALL    /* =======================================================       3. GOODS ISSUE – NVL / BOM COMPONENT       ======================================================= */    SELECT DISTINCT        J.TransId,        I1.U_belnrid,        I1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit,        I1.ItemCode,        I1.Quantity,        I1.WhsCode,        IG.ItmsGrpNam,        I1.StockPrice                        AS ItemCost,        I1.Quantity * I1.StockPrice          AS ItemAmount,        OG.DocDate                           AS PostingDate,        'GI_NVL'    FROM JDT1 J    INNER JOIN OJDT OJ   ON OJ.TransId   = J.TransId    INNER JOIN OIGE OG  ON OJ.CreatedBy = OG.DocEntry    INNER JOIN IGE1 I1  ON OG.DocEntry  = I1.DocEntry    INNER JOIN OITM IM  ON I1.ItemCode  = IM.ItemCode    INNER JOIN OITB IG  ON IM.ItmsGrpCod = IG.ItmsGrpCod    LEFT JOIN OACT O    ON J.Account    = O.AcctCode    WHERE OJ.TransType = 60      AND I1.U_belnrid  IS NOT NULL      AND I1.U_belposid IS NOT NULL    UNION ALL    /* =======================================================       4. GOODS RECEIPT – FINISHED GOOD       ======================================================= */    SELECT DISTINCT        J.TransId,        R1.U_belnrid,        R1.U_belposid,        O.AcctCode,        J.Debit,        J.Credit,        R1.ItemCode,        R1.Quantity,        R1.WhsCode,        IG.ItmsGrpNam,        R1.StockPrice                        AS ItemCost,        R1.Quantity * R1.StockPrice          AS ItemAmount,        ORH.DocDate                          AS PostingDate,        'GR_FG'    FROM JDT1 J    INNER JOIN OJDT OJ   ON OJ.TransId   = J.TransId    INNER JOIN OIGN ORH ON OJ.CreatedBy = ORH.DocEntry    INNER JOIN IGN1 R1  ON ORH.DocEntry = R1.DocEntry    INNER JOIN OITM IM  ON R1.ItemCode  = IM.ItemCode    INNER JOIN OITB IG  ON IM.ItmsGrpCod = IG.ItmsGrpCod    LEFT JOIN OACT O    ON J.Account    = O.AcctCode    WHERE OJ.TransType = 59      AND R1.U_belnrid  IS NOT NULL      AND R1.U_belposid IS NOT NULL)/* ================== DETAIL CHECK REPORT ================== */SELECT    D.BELNR_ID        AS 'WO Number',    D.BELPOS_ID       AS 'WO Position',    P.ABGKZ_DATE      AS 'WO Close Date',      -- 🔒 FILTER THEO NGÀY NÀY    D.PostingDate     AS 'Posting Date',    H.BELDAT          AS 'WO Create Date',    D.TransId         AS 'TransId',    D.SrcType         AS 'Source Type',    D.Account         AS 'GL Account',    D.ItemCode        AS 'Item Code',    D.Quantity        AS 'Quantity',    D.WhsCode         AS 'Warehouse',    D.ItemGroup       AS 'Item Group',    D.ItemCost        AS 'Unit Cost',    D.ItemAmount      AS 'Item Amount',    D.Debit,    D.Credit,    (D.Debit - D.Credit) AS 'GL Amount'FROM BEAS_COST_DETAIL DINNER JOIN BEAS_FTPOS P    ON P.BELNR_ID  = D.BELNR_ID   AND P.BELPOS_ID = D.BELPOS_IDINNER JOIN BEAS_FTHAUPT H    ON H.BELNR_ID = D.BELNR_IDWHERE    P.ABGKZ_DATE BETWEEN @FromDate AND @ToDate   -- ✅ CHỈ FILTER THEO CLOSE WOORDER BY    D.BELNR_ID,    D.BELPOS_ID,    D.PostingDate,    D.TransId,    D.SrcType,    D.ItemCode;